     2| * IVX Member Registration API Handlers
     3| *
     4| * Endpoints:
     5| *   POST /api/members/register         - Create free account
     6| *   POST /api/members/send-email-code  - Generate + send email verification code
     7| *   POST /api/members/verify-email     - Verify email code
     8| *   POST /api/members/send-phone-code  - Generate + send phone verification code
     9| *   POST /api/members/verify-phone     - Verify phone code
    10| *   GET  /api/members/me               - Get current member profile
    11| *   POST /api/members/start-kyc        - Initiate KYC process
    12| */
    13|
    14|import {
    15|  registerMember,
    16|  getMemberProfile,
    17|  updateMemberKYCStatus,
    18|  updateMemberLastLogin,
    19|  loginMember,
