    26|import { upsertCanonicalMember, markCanonicalMemberVerified } from '../services/ivx-canonical-members';
    27|import {
    28|  orchestrateRegistration,
    29|  getRegistrationStatus,
    30|  checkRegistrationHealth,
    31|  getRegistrationMetrics,
    32|  type RegistrationRequestInput,
    33|  type NormalizedRegistrationResult,
