    41|function jsonResponse(data: unknown, status = 200): Response {
    42|  return new Response(JSON.stringify(data), {
    43|    status,
    44|    headers: {
    45|      'Content-Type': 'application/json',
    46|      'Access-Control-Allow-Origin': 'https://ivxholding.com',
    47|      'Access-Control-Allow-Headers': 'Content-Type, Authorization',
