    52|async function parseBody(request: Request): Promise<Record<string, unknown>> {
    53|  try {
    54|    return (await request.json()) as Record<string, unknown>;
    55|  } catch {
    56|    return {};
    57|  }
    58|}
    59|
    60|function asString(value: unknown, fallback = ''): string {
    61|  if (typeof value === 'string') return value.trim();
    62|  return fallback;
    63|}
    64|
    65|function getAuthUserId(request: Request): string | null {
    66|  const authHeader = request.headers.get('Authorization') || '';
    67|  const match = authHeader.match(/^Bearer\s+(.+)$/i);
    68|  return match ? match[1] : null;
    69|}
    70|
    71|// Validate email format
    72|function isValidEmail(email: string): boolean {
    73|  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    74|}
    75|
    76|// Validate date of birth: required, ISO YYYY-MM-DD, real calendar date, age 18-120
    77|function validateDateOfBirth(dateOfBirth: string): { valid: boolean; reason?: string } {
    78|  if (!dateOfBirth) return { valid: false, reason: 'Date of birth is required.' };
    79|  const match = dateOfBirth.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    80|  if (!match) return { valid: false, reason: 'Date of birth must be in YYYY-MM-DD format.' };
    81|  const year = Number(match[1]);
    82|  const month = Number(match[2]);
    83|  const day = Number(match[3]);
    84|  if (month < 1 || month > 12) return { valid: false, reason: 'Please enter a valid date of birth.' };
    85|  const daysInMonth = new Date(Date.UTC(year, month, 0)).getUTCDate();
    86|  if (day < 1 || day > daysInMonth) return { valid: false, reason: 'Please enter a valid date of birth.' };
    87|  const now = new Date();
    88|  let age = now.getUTCFullYear() - year;
    89|  const hadBirthdayThisYear =
    90|    now.getUTCMonth() + 1 > month || (now.getUTCMonth() + 1 === month && now.getUTCDate() >= day);
    91|  if (!hadBirthdayThisYear) age -= 1;
    92|  if (age < 18) return { valid: false, reason: 'You must be at least 18 years old to create an account.' };
    93|  if (age > 120) return { valid: false, reason: 'Please enter a valid date of birth.' };
    94|  return { valid: true };
    95|}
