    97|const VALID_GENDERS = new Set(['male', 'female', 'prefer_not_to_say']);
    98|
    99|// Validate gender: required, must be one of the allowed values
   100|function validateGender(gender: string): { valid: boolean; reason?: string } {
   101|  if (!gender) return { valid: false, reason: 'Gender is required.' };
   102|  if (!VALID_GENDERS.has(gender)) {
   103|    return { valid: false, reason: 'Please select a valid gender option.' };
   104|  }
   105|  return { valid: true };
   106|}
   107|
   108|// Validate password strength
   109|function validatePassword(password: string): { valid: boolean; reason?: string } {
   110|  if (password.length < 8) return { valid: false, reason: 'Password must be at least 8 characters.' };
   111|  if (!/[A-Z]/.test(password)) return { valid: false, reason: 'Password must contain at least 1 uppercase letter.' };
   112|  if (!/[0-9]/.test(password)) return { valid: false, reason: 'Password must contain at least 1 number.' };
   113|  return { valid: true };
   114|}
