   201|// --- Normalized response helpers (Phase 2 contract) ---
   202|
   203|function normalizedError(code: RegistrationErrorCode, stage: RegistrationStage, overrides?: { message?: string; retryable?: boolean; registrationRequestId?: string }): Response {
   204|  const traceId = 'ivx-reg-' + Date.now().toString(36) + '-' + Math.random().toString(36).substring(2, 10);
   205|  const body = {
   206|    ok: false as const,
   207|    code,
   208|    message: overrides?.message ?? code,
   209|    traceId,
   210|    stage,
   211|    retryable: overrides?.retryable ?? false,
   212|    registrationRequestId: overrides?.registrationRequestId,
   213|    deploymentMarker: DEPLOYMENT_MARKER,
   214|  };
   215|  const status = code === 'EMAIL_EXISTS' ? 409 : code === 'RATE_LIMITED' ? 429 : (code === 'NETWORK_ERROR' || code === 'SERVICE_UNAVAILABLE') ? 503 : 400;
   216|  return jsonResponse(body, status);
   217|}
   218|
   219|function normalizedResponse(result: NormalizedRegistrationResult): Response {
   220|  if (result.ok) {
   221|    // Fire-and-forget verification codes + onboarding fanout (kept identical to prior behavior).
   222|    storeVerificationCode({ userId: result.authUserId, type: 'email' }).catch(() => {});
   223|    storeVerificationCode({ userId: result.authUserId, type: 'phone' }).catch(() => {});
   224|    return jsonResponse({ ...result, deploymentMarker: DEPLOYMENT_MARKER }, 200);
   225|  }
   226|  const status = result.code === 'EMAIL_EXISTS' ? 409 : result.code === 'RATE_LIMITED' ? 429 : (result.code === 'NETWORK_ERROR' || result.code === 'SERVICE_UNAVAILABLE') ? 503 : 400;
   227|  return jsonResponse({ ...result, deploymentMarker: DEPLOYMENT_MARKER }, status);
   228|}
