   230|// GET /api/ivx/registration/status?id=<registrationRequestId>
   231|export async function handleRegistrationStatusRequest(request: Request): Promise<Response> {
   232|  const url = new URL(request.url);
   233|  const id = url.searchParams.get('id') || '';
   234|  if (!id) {
   235|    return normalizedError('UNKNOWN_ERROR', 'IDLE', { message: 'Registration request ID is required.' });
   236|  }
   237|  const { found, state } = await getRegistrationStatus(id);
   238|  if (!found || !state) {
   239|    return jsonResponse({ ok: false, found: false, message: 'No registration found for that ID.', traceId: 'ivx-reg-status-' + Date.now().toString(36), deploymentMarker: DEPLOYMENT_MARKER }, 404);
   240|  }
   241|  // Never expose the email hash or auth user ID directly — only stage + status.
   242|  return jsonResponse({
   243|    ok: true,
   244|    found: true,
   245|    registrationRequestId: state.registrationRequestId,
   246|    stage: state.stage,
   247|    finalStatus: state.finalStatus,
   248|    createdAt: state.createdAt,
   249|    updatedAt: state.updatedAt,
   250|    lastErrorCode: state.lastErrorCode,
   251|    deploymentMarker: DEPLOYMENT_MARKER,
   252|  }, 200);
   253|}
