     2| * IVX Registration Orchestrator — Phase 2 reliability hardening.
     3| *
     4| * Wraps the existing `registerMember` pipeline with:
     5| *  - idempotency via `registrationRequestId` (one key = one logical registration)
     6| *  - explicit state machine (IDLE → VALIDATING → … → COMPLETED / RECOVERABLE_ERROR / BLOCKED)
     7| *  - partial-failure recovery (Auth exists / member missing / interest missing / session missing)
     8| *  - normalized error format with stable codes + traceId (no raw stack traces, no secrets)
     9| *  - bounded retries with exponential backoff (network / 5xx only — never for validation / auth / duplicates)
    10| *  - durable persistence of registration state so a timeout or browser refresh can resume safely
    11| *  - production-safe telemetry (no passwords, tokens, PII in logs)
    12| *
    13| * Security invariants:
    14| *  - passwords are NEVER logged, persisted to durable store, or included in telemetry
    15| *  - access / refresh tokens are NEVER persisted to durable store
    16| *  - only the normalized email hash + request ID + stage + timestamps are persisted
    17| *
    18| * Endpoint surface:
    19| *  - POST /api/members/register            (existing, now accepts registrationRequestId)
    20| *  - GET  /api/ivx/registration/status?id=  (resume / inspect existing request)
    21| *  - GET  /api/ivx/registration/health      (config + Supabase + tables reachable)
    22| */
    23|import { randomUUID, createHash } from 'node:crypto';
    24|import { createClient } from '@supabase/supabase-js';
    25|import { registerMember, type MemberRegistrationInput } from './ivx-member-database';
    26|import { onboardNewMember, VALID_ROLE_INTERESTS, type MemberRoleInterest } from './ivx-member-investor-system';
    27|import { upsertCanonicalMember } from './ivx-canonical-members';
    28|import { isDurableStoreConfigured, readDurableJson, writeDurableJson } from './ivx-durable-store';
    29|
    30|// ---------------------------------------------------------------------------
    31|// Role-specific record creation — inserts into jv_partners, brokers, agents,
    32|// land_owners, tokenized_investors, investors, buyers based on selected roles.
    33|// Non-fatal: logs errors but does not block registration completion.
    34|// ---------------------------------------------------------------------------
    35|
    36|const ROLE_TABLE_MAP: Record<string, string> = {
    37|  investor: 'investors',
    38|  buyer: 'buyers',
    39|  jv_partner: 'jv_partners',
    40|  broker: 'brokers',
    41|  agent: 'agents',
    42|  land_owner: 'land_owners',
    43|  tokenized: 'tokenized_investors',
    44|};
    45|
    46|/** Per-table row builder — each role table has a different schema. */
    47|function buildRoleRow(role: string, tableName: string, authUserId: string, email: string): Record<string, unknown> {
    48|  const now = new Date().toISOString();
    49|  const base = { status: 'active', created_at: now, updated_at: now };
    50|
    51|  switch (tableName) {
    52|    case 'investors':
    53|      // investors table: user_id (uuid), full_name (NOT NULL), email (NOT NULL), accreditation, investment_tier, status
    54|      return { user_id: authUserId, full_name: email.split('@')[0], email, status: 'active', accreditation: 'pending', investment_tier: 'standard', created_at: now, updated_at: now };
    55|    case 'buyers':
    56|      // buyers table: id (text, NOT NULL), name (NOT NULL), email, buyer_type, status
    57|      return { id: authUserId, name: email.split('@')[0], email, status: 'active', buyer_type: 'individual', created_at: now, updated_at: now };
    58|    default:
    59|      // jv_partners, brokers, agents, land_owners, tokenized_investors: auth_user_id (uuid), status, created_at, updated_at
    60|      return { auth_user_id: authUserId, ...base };
    61|  }
    62|}
    63|
    64|function getConflictColumn(tableName: string): string {
    65|  switch (tableName) {
    66|    case 'investors': return 'user_id';
    67|    case 'buyers': return 'id';
    68|    default: return 'auth_user_id';
    69|  }
    70|}
    71|
    72|async function insertRoleSpecificRecords(input: {
    73|  authUserId: string;
    74|  email: string;
    75|  roles: MemberRoleInterest[];
    76|  registrationRequestId: string;
    77|}): Promise<{ ok: boolean; errors: string[] }> {
    78|  const errors: string[] = [];
    79|  const supabase = getSupabaseAdmin();
    80|
    81|  for (const role of input.roles) {
    82|    const tableName = ROLE_TABLE_MAP[role];
    83|    if (!tableName) continue; // Skip 'jv_deals' and unknown roles
    84|
