   374|// ---------------------------------------------------------------------------
   375|// Public API
   376|// ---------------------------------------------------------------------------
   377|
   378|/**
   379| * Idempotent registration orchestrator.
   380| *
   381| * One `registrationRequestId` always maps to at most one logical registration:
   382| *  - duplicate submissions return the existing result
   383| *  - a timed-out client can call again with the same ID and resume
   384| *  - partial failures (Auth ok, profile missing) are repaired, not duplicated
   385| */
   386|export async function orchestrateRegistration(
   387|  input: RegistrationRequestInput
   388|): Promise<NormalizedRegistrationResult> {
   389|  const traceId = generateTraceId();
   390|  const registrationRequestId = input.registrationRequestId || randomUUID();
   391|  const normalizedEmail = normalizeEmail(input.email);
   392|  const emailHash = hashEmail(normalizedEmail);
   393|
   394|  // Step 1: validate (never calls backend)
   395|  if (!input.firstName || !input.lastName) {
   396|    return makeError('INVALID_EMAIL', 'VALIDATING', traceId, registrationRequestId, {
   397|      message: 'First name and last name are required.',
   398|      retryable: false,
   399|    });
   400|  }
   401|  if (!isValidEmail(normalizedEmail)) {
   402|    return makeError('INVALID_EMAIL', 'VALIDATING', traceId, registrationRequestId, { retryable: false });
   403|  }
   404|  const pwCheck = validatePasswordPolicy(input.password);
   405|  if (!pwCheck.valid) {
   406|    return makeError('WEAK_PASSWORD', 'VALIDATING', traceId, registrationRequestId, {
   407|      message: pwCheck.reason ?? 'Password does not meet requirements.',
   408|      retryable: false,
   409|    });
   410|  }
   411|  if (!input.acceptTerms) {
   412|    return makeError('UNKNOWN_ERROR', 'VALIDATING', traceId, registrationRequestId, {
   413|      message: 'You must accept the Terms of Service.',
   414|      retryable: false,
   415|    });
   416|  }
   417|
   418|  // Step 2: idempotency — resume an existing in-flight or completed request
   419|  const existing = await loadRegistrationState(registrationRequestId);
   420|  if (existing && existing.finalStatus === 'completed' && existing.authUserId) {
   421|    // Duplicate submission for an already-completed request → return the same result.
   422|    return {
   423|      ok: true,
   424|      stage: 'COMPLETED',
   425|      registrationRequestId,
   426|      traceId,
   427|      authUserId: existing.authUserId,
   428|      email: normalizedEmail,
   429|      requiresVerification: false,
   430|      resumeToken: existing.registrationRequestId,
   431|    };
   432|  }
   433|  if (existing && existing.finalStatus === 'pending' && existing.stage === 'AUTH_CREATING') {
   434|    // A previous call crashed mid-auth — do NOT blindly create a second user.
   435|    // Surface a recoverable error so the client can poll status and resume.
   436|    return makeError('AUTH_CREATION_FAILED', 'AUTH_CREATING', traceId, registrationRequestId, {
   437|      message: 'A previous attempt is still being processed. Please wait a moment and try again.',
   438|      retryable: true,
   439|    });
   440|  }
   441|
   442|  // Step 3: persist initial state (no password, no token — only hash + IDs + stage)
   443|  const initialState: PersistedRegistrationState = {
   444|    registrationRequestId,
   445|    traceId,
   446|    normalizedEmailHash: emailHash,
   447|    opportunityId: input.opportunityId,
   448|    stage: 'SUBMITTING',
   449|    finalStatus: 'pending',
   450|    createdAt: new Date().toISOString(),
   451|    updatedAt: new Date().toISOString(),
   452|  };
   453|  await saveRegistrationState(initialState);
   454|
   455|  // Step 4: execute the registration pipeline with bounded retries.
   456|  // The underlying `registerMember` already does Auth + profile + wallet + audit
   457|  // + onboarding fanout + canonical member sync. We retry the WHOLE pipeline only
   458|  // for network/5xx errors; validation / auth / duplicate errors are not retried.
   459|  const maxAttempts = 3;
   460|  let lastError: NormalizedRegistrationError | null = null;
   461|
   462|  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
   463|    const delay = backoffDelay(attempt);
   464|    if (delay > 0) await sleep(delay);
   465|
   466|    await saveRegistrationState({
   467|      ...initialState,
   468|      stage: 'AUTH_CREATING',
   469|      updatedAt: new Date().toISOString(),
   470|    });
   471|
   472|    const result = await registerMember({
   473|      email: normalizedEmail,
   474|      password: input.password,
   475|      firstName: input.firstName,
   476|      lastName: input.lastName,
   477|      dateOfBirth: input.dateOfBirth,
   478|      gender: input.gender,
   479|      phone: input.phone,
   480|      country: input.country,
   481|      zipCode: input.zipCode,
   482|      roles: input.roles,
   483|      acceptTerms: input.acceptTerms,
   484|      pictureUrl: input.pictureUrl,
   485|    });
   486|
   487|    if (result.success && result.userId) {
   488|      const authUserId = result.userId;
   489|
   490|      // --- PROFILE_CREATING stage ---
   491|      await saveRegistrationState({
   492|        ...initialState,
   493|        authUserId,
   494|        stage: 'PROFILE_CREATING',
   495|        updatedAt: new Date().toISOString(),
   496|      });
   497|
   498|      // Canonical member sync (Supabase `members` table) — non-fatal but logged.
   499|      const fanoutErrors: { step: string; error: string }[] = [];
   500|      try {
   501|        const canonicalResult = await upsertCanonicalMember({
   502|          fullName: `${input.firstName} ${input.lastName}`.trim(),
   503|          email: normalizedEmail,
   504|          phone: input.phone,
   505|          memberType: input.roles && input.roles.length > 0 ? input.roles[0] : 'member',
   506|          source: 'landing_page',
   507|          sourceDetail: 'registration-orchestrator',
   508|          verificationStatus: 'unverified',
   509|          smsVerified: false,
   510|          emailVerified: false,
   511|          investorInterest: input.roles ? input.roles.join(',') : '',
   512|          preferredZipcode: input.zipCode || '',
   513|          budgetRange: '',
   514|          authUserId,
   515|          landingSubmissionId: registrationRequestId,
   516|          pictureUrl: input.pictureUrl || '',
   517|          // --- Canonical identity model fields (ITEM 1) ---
   518|          countryCode: input.country || undefined,
   519|          primaryRole: input.roles && input.roles.length > 0 ? input.roles[0] : 'member',
   520|          secondaryRoles: input.roles && input.roles.length > 1 ? input.roles.slice(1) : [],
   521|          registrationType: 'individual',
   522|          registrationStatus: 'completed',
   523|          identityStatus: 'active',
   524|          kycStatus: 'not_started',
   525|          amlStatus: 'not_started',
   526|          ownerReviewStatus: 'not_started',
   527|          sourceChannel: 'landing_page',
   528|          dataOrigin: 'auth_users',
   529|          termsVersion: input.acceptTerms ? 'v1' : undefined,
   530|          privacyVersion: input.acceptTerms ? 'v1' : undefined,
   531|          termsAcceptedAt: input.acceptTerms ? new Date().toISOString() : undefined,
   532|          auditTraceId: traceId,
   533|        });
   534|        if (canonicalResult && canonicalResult.ok === false) {
   535|          fanoutErrors.push({ step: 'canonical', error: canonicalResult.error || 'unknown' });
   536|          console.error('[RegistrationOrchestrator] upsertCanonicalMember failed:', canonicalResult.error || 'unknown');
   537|        }
   538|      } catch (canonicalErr) {
   539|        fanoutErrors.push({ step: 'canonical', error: canonicalErr instanceof Error ? canonicalErr.message : 'unknown' });
   540|        console.error('[RegistrationOrchestrator] upsertCanonicalMember failed:', canonicalErr instanceof Error ? canonicalErr.message : 'unknown');
   541|      }
   542|
   543|      // Onboarding fanout (file-based member store) — non-fatal but logged.
   544|      try {
   545|        await onboardNewMember({
   546|          userId: authUserId,
   547|          firstName: input.firstName,
   548|          lastName: input.lastName,
   549|          email: normalizedEmail,
   550|          phone: input.phone,
   551|          country: input.country || '',
   552|          zipCode: input.zipCode || '',
   553|          roles: (input.roles || []).filter((r): r is MemberRoleInterest => VALID_ROLE_INTERESTS.has(r as MemberRoleInterest)),
   554|          pictureUrl: input.pictureUrl,
   555|        });
   556|      } catch (onboardErr) {
   557|        console.error('[RegistrationOrchestrator] onboardNewMember failed:', onboardErr instanceof Error ? onboardErr.message : 'unknown');
   558|      }
   559|
   560|      // --- ROLE_PROFILE_CREATING stage ---
   561|      // Insert role-specific records into investors, buyers, jv_partners, brokers,
   562|      // agents, land_owners, tokenized_investors based on selected roles.
   563|      // Non-fatal: logs errors but does not block registration completion.
   564|      const roleRoles = (input.roles || []).filter((r): r is MemberRoleInterest => VALID_ROLE_INTERESTS.has(r as MemberRoleInterest));
   565|      if (roleRoles.length > 0) {
   566|        const roleResult = await insertRoleSpecificRecords({
   567|          authUserId,
   568|          email: normalizedEmail,
   569|          roles: roleRoles,
   570|          registrationRequestId,
   571|        });
   572|        if (!roleResult.ok) {
   573|          for (const re of roleResult.errors) {
   574|            fanoutErrors.push({ step: 'role_specific', error: String(re) });
   575|          }
   576|        }
   577|      }
   578|
   579|      // --- INTEREST_CREATING stage ---
   580|      await saveRegistrationState({
   581|        ...initialState,
   582|        authUserId,
   583|        stage: 'INTEREST_CREATING',
   584|        updatedAt: new Date().toISOString(),
   585|      });
   586|
   587|      // Investment interest row (Supabase `landing_investments` table) — non-fatal but logged.
   588|      if (input.opportunityId || input.opportunityTitle || input.amount) {
   589|        const interestResult = await insertInvestmentInterest({
   590|          authUserId,
   591|          email: normalizedEmail,
   592|          registrationRequestId,
   593|          opportunityId: input.opportunityId,
   594|          opportunityTitle: input.opportunityTitle,
   595|          amount: input.amount,
   596|          investmentType: input.investmentType,
   597|        });
   598|        if (!interestResult.ok) {
   599|          console.error('[RegistrationOrchestrator] insertInvestmentInterest failed:', interestResult.error);
   600|        }
   601|      }
   602|
   603|      // --- COMPLETED ---
   604|      await saveRegistrationState({
   605|        ...initialState,
   606|        authUserId,
   607|        stage: 'COMPLETED',
   608|        finalStatus: 'completed',
   609|        updatedAt: new Date().toISOString(),
   610|      });
   611|
   612|      return {
   613|        ok: true,
   614|        stage: 'COMPLETED',
   615|        registrationRequestId,
   616|        traceId,
   617|        authUserId,
   618|        email: normalizedEmail,
   619|        requiresVerification: false,
   620|        resumeToken: registrationRequestId,
   621|        fanoutErrors: fanoutErrors.length > 0 ? fanoutErrors : undefined,
   622|      };
   623|    }
   624|
   625|    // Failure — classify and decide whether to retry.
   626|    const code = classifyAuthError(result.message);
   627|    lastError = makeError(code, 'AUTH_CREATING', traceId, registrationRequestId);
